const VALID_PRIORITIES = new Set(["low", "medium", "high", "urgent"]);
const VALID_TASK_TYPES = new Set(["task", "follow_up"]);
const CLEARABLE_FIELDS = new Set([
  "notes",
  "due",
  "deadline",
  "requested_date",
  "requested_time",
  "parent_task_id",
  "follow_up_of",
]);
const PATCH_FIELDS = new Set([
  "title",
  "notes",
  "due",
  "date",
  "deadline",
  "requested_date",
  "requested_time",
  "priority",
  "estimated_duration",
  "fixed_time",
  "timezone",
  "task_type",
  "parent_task_id",
  "follow_up_of",
  "follow_up_sequence",
]);

function hasOwn(value, key) {
  return Boolean(value && Object.hasOwn(value, key));
}

function validDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value || ""))) return false;
  const parsed = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(parsed.valueOf()) && parsed.toISOString().slice(0, 10) === value;
}

function validTime(value) {
  return typeof value === "string" && /^(?:[01]\d|2[0-3]):[0-5]\d$/.test(value);
}

function cleanOptionalString(value, name, maxLength) {
  if (value === null) return null;
  if (typeof value !== "string") throw new Error(`${name} must be a string or null`);
  const clean = value.trim();
  if (!clean || clean.length > maxLength) throw new Error(`${name} must contain 1-${maxLength} characters`);
  return clean;
}

function normalizedText(value) {
  return String(value || "")
    .toLocaleLowerCase()
    .normalize("NFKC")
    .replace(/[\s\p{P}\p{S}]+/gu, "");
}

function newestTimestamp(...values) {
  return values
    .filter(Boolean)
    .map(String)
